            "mcp.method.name": ctx.method,
            "mcp.protocol.version": ctx.protocol_version,
        }",
      "replace": "attributes: dict[str, Any] = {
            "mcp.method.name": ctx.method,
            "mcp.protocol.version": ctx.protocol_version,
        }
        # Record the number of top‑level request parameters, if we can determine it.
        if ctx.params is not None:
            try:
                attributes["mcp.method.params.count"] = len(ctx.params)
            except Exception:
                # ctx.params might not be a sized container (e.g., a Pydantic model);
                # in that case we simply omit the count.
                pass"
