  "test": "import pytest
from opentelemetry.trace import SpanKind, StatusCode
from mcp.server._otel import OpenTelemetryMiddleware
from mcp.server.lowlevel.server import Server
from mcp.server.context import CallNext
from .conftest import SpanCapture
from mcp_types import CallToolRequestParams

@pytest.fixture
def server() -> Server:
    async def dummy_tool(ctx, params: CallToolRequestParams):
        return {"content": [], "isError": False}
    srv = Server(name="test-server", version="0.0.1")
    srv.add_request_handler("tools/call", CallToolRequestParams, dummy_tool)
    return srv

@pytest.mark.anyio
async def test_param_count_attribute_present(server: Server, spans: SpanCapture):
    async with server.run() as (client, _):
        spans.clear()
        await client.send_raw_request("tools/call", {"name": "mytool", "arguments": {}})
    [span] = [s for s in spans.finished() if s.kind == SpanKind.SERVER]
    # The request dict has two top‑level keys: "name" and "arguments"
    assert span.attributes is not None
    assert span.attributes["mcp.method.params.count"] == 2
    assert span.status.status_code == StatusCode.UNSET
